	@Test
	public void adjacencyProviderProbesOnlyTheKeysTheProbeProduces() {
		String[] variables = { "sourceClass", "instanceCount", "targetClass", "edgeCount" };
		List<String> expected = rows(referenceRepository, CENSUS, variables);
		long sourceClasses = expected.stream().map(row -> row.substring(0, row.indexOf('|'))).distinct().count();
		long allClasses = rows(referenceRepository,
				PREFIXES + "SELECT DISTINCT ?class WHERE { ?member rdf:type ?class }", "class").size();
		assertThat(sourceClasses).as("a class without edges never appears as a source class").isLessThan(allClasses);

		long buildsBefore = NativeKeyedSubqueryJoinPlan.GENERIC_INDEX_BUILDS.get();
		long probesBefore = NativeKeyedSubqueryJoinPlan.ADJACENCY_KEY_PROBES.get();
		List<String> actual = rows(nativeRepository, CENSUS, variables);
		long builds = NativeKeyedSubqueryJoinPlan.GENERIC_INDEX_BUILDS.get() - buildsBefore;
		long probes = NativeKeyedSubqueryJoinPlan.ADJACENCY_KEY_PROBES.get() - probesBefore;

		assertThat(actual).isEqualTo(expected);
		assertThat(builds).as("the fast path must not materialize the subquery").isZero();
		assertThat(probes).as("one adjacency probe per distinct source class").isEqualTo(sourceClasses);
	}

	@Test
	public void typingsDuplicatedAcrossGraphsAreCountedOnce() {
		String query = PREFIXES + "SELECT ?members WHERE {\n"
				+ "  { SELECT ?category (COUNT(DISTINCT ?member) AS ?members) WHERE { ?member rdf:type ?category . } GROUP BY ?category }\n"
				+ "  ex:i1 ex:category ?category .\n"
				+ "}";
		List<String> expected = rows(referenceRepository, query, "members");
		assertThat(expected).hasSize(1);
		assertThat(rows(nativeRepository, query, "members")).isEqualTo(expected);
		assertThat(telemetry(nativeRepository, query)).contains(ADJACENCY_TAG);
		// the five nodes typed T0 in three graphs count once each, on top of the random typings
		long members = Long.parseLong(expected.get(0).replaceAll("\"\\^\\^.*", "").replace("\"", ""));
		long distinct = Long.parseLong(rows(referenceRepository,
				PREFIXES + "SELECT (COUNT(DISTINCT ?m) AS ?n) WHERE { ?m rdf:type ex:T0 }", "n").get(0)
						.replaceAll("\"\\^\\^.*", "")
						.replace("\"", ""));
		assertThat(members).isEqualTo(distinct);
	}

