	@Test
	public void committedDeltaTakesTheDecodeFallback() {
		LmdbStore nativeStore = (LmdbStore) nativeRepository.getSail();
		try {
			for (SailRepository repository : List.of(nativeRepository, referenceRepository)) {
				try (SailRepositoryConnection connection = repository.getConnection()) {
					ValueFactory vf = connection.getValueFactory();
					connection.begin();
					connection.add(vf.createIRI(EX, "late1"), RDF.TYPE, vf.createIRI(EX, "T0"));
					connection.add(vf.createIRI(EX, "late2"), RDF.TYPE, vf.createIRI(EX, "Fresh"));
					connection.add(vf.createIRI(EX, "iF"), vf.createIRI(EX, "category"), vf.createIRI(EX, "Fresh"));
					connection.remove(vf.createIRI(EX, "lonely0"), RDF.TYPE, vf.createIRI(EX, "Lonely"));
					connection.commit();
				}
			}
			// resuming the applier waits until the commit is folded into the delta over the built base
			AdjacencyEngagementTestAccess.pauseApplier(nativeStore, false);
			String[] variables = { "item", "category", "members" };
			List<String> expected = rows(referenceRepository, MISSING_KEYS, variables);
			assertThat(expected).anyMatch(row -> row.contains("Fresh"));

			long decodesBefore = NativeKeyedSubqueryJoinPlan.ADJACENCY_DECODE_COUNTS.get();
			List<String> actual = rows(nativeRepository, MISSING_KEYS, variables);
			assertThat(actual).isEqualTo(expected);
			assertThat(NativeKeyedSubqueryJoinPlan.ADJACENCY_DECODE_COUNTS.get() - decodesBefore)
					.as("a committed delta cannot be answered from metadata")
					.isGreaterThan(0L);
		} finally {
			AdjacencyEngagementTestAccess.pauseApplier(nativeStore, false);
		}
	}

	@Test
	public void uncommittedTransactionDataIsVisibleInTheSameConnection() {
		String[] variables = { "item", "category", "members" };
		List<List<String>> results = new ArrayList<>();
		for (SailRepository repository : List.of(nativeRepository, referenceRepository)) {
			try (SailRepositoryConnection connection = repository.getConnection()) {
				ValueFactory vf = connection.getValueFactory();
				connection.begin();
				connection.add(vf.createIRI(EX, "pending1"), RDF.TYPE, vf.createIRI(EX, "T0"));
				connection.add(vf.createIRI(EX, "pending2"), RDF.TYPE, vf.createIRI(EX, "Pending"));
				connection.add(vf.createIRI(EX, "iP"), vf.createIRI(EX, "category"), vf.createIRI(EX, "Pending"));
				List<String> rows = new ArrayList<>();
				for (BindingSet bindings : QueryResults.asList(connection.prepareTupleQuery(MISSING_KEYS).evaluate())) {
					StringBuilder row = new StringBuilder();
					for (String variable : variables) {
						row.append(bindings.getValue(variable)).append('|');
					}
					rows.add(row.toString());
				}
				Collections.sort(rows);
				results.add(rows);
				connection.rollback();
			}
		}
		assertThat(results.get(1)).anyMatch(row -> row.contains("Pending"));
		assertThat(results.get(0)).isEqualTo(results.get(1));
	}

